SELECT id, account, is_admin AS isAdmin, can_edit_credit AS canEditCredit, is_deleted AS isDeleted FROM user_config
AND account LIKE CONCAT('%', #{account}, '%')
LIMIT #{limit} OFFSET #{offset}

SELECT id, account, is_admin AS isAdmin, can_edit_credit AS canEditCredit, is_deleted AS isDeleted FROM user_config WHERE account IN
#{acc}
ORDER BY id DESC

mapper.update:
UPDATE user_config
SET account = #{account},
    is_admin = #{isAdmin},
    can_edit_credit = #{canEditCredit},
    is_deleted = #{isDeleted}
WHERE id = #{id}

UPDATE user_config
SET is_deleted = '1'
WHERE id = #{id}
